def find_local_uuid (tw,keys,issue,legacy_matching = False):
    if not issue['description']:
        raise ValueError('Issue %s has no description.' % issue)
    possibilities = set([])
    if legacy_matching:
        legacy_description = issue.get_default_description().rsplit('..',1)[0]
        legacy_description = legacy_description.split("'")[0]
        results = tw.filter_tasks({'description.startswith':legacy_description,'or':[('status','pending'),('status','waiting'),],})
        possibilities = possibilities | set([task['uuid'] for task in results])
    for service,key_list in six.iteritems(keys):
        if any([key in issue for key in key_list]):
            results = tw.filter_tasks({'and':[("%s.is" % key,issue[key]) for key in key_list],'or':[('status','pending'),('status','waiting'),],})
            possibilities = possibilities | set([task['uuid'] for task in results])
    if len(possibilities)==1:
        return possibilities.pop()
    if len(possibilities)>1:
        raise MultipleMatches("Issue %s matched multiple IDs: %s" % (issue['description'],possibilities))
    raise NotFound("No issue was found matching %s" % issue)

