def top (df,value:str,limit:int,order:str = 'asc',group:Union [ str,List [ str ] ] = None):
    ascending = order != 'desc'
    limit = int (limit)
    filter_func = 'nlargest' if (limit > 0)^ ascending else 'nsmallest'
