def split_line(line, min_line_length=30, max_line_length=100):
    if len(line) <= max_line_length:
        return [line]
    # compute indentation
    indent = 0
    while line[indent] == ' ' and indent < len(line):
        indent += 1
    # find split point
    i = max_line_length
    split_point = None
    while i > min_line_length:
        if line[i] == ' ':
            split_point = i
            break
        i -= 1
    if split_point is None:
        i = max_line_length + 1
        while i < len(line):
            if line[i] == ' ':
                split_point = i
                break
            i += 1
    if split_point is None:
        return [line]
    else:
        line1 = line[:split_point]
        line2 = ' ' * indent + line[split_point+1:]
        return [line1] + split_line(line2, min_line_length, max_line_length)

So it splits a long line into multiple lines, respecting indentation and splitting at spaces near max_line_length, but ensuring each line is at least min_line_length. It returns a list of lines.

