def _get_attrib(self, attr, convert_to_str=False):
    if attr.startswith('tags.'):
        tag = attr[len('tags.'):]
        if tag in self.tags and self.tags[tag] != '':
            return self.tags[tag]
        elif convert_to_str is True:
            return '<not set>'
        else:
            return self.tags.get(tag)
