        raise AttributeError('Invalid attribute: {0}. Perhaps you meant ' '{1}?'.format(red(attr), green('tags.' + attr)))
    else:
        result = getattr(self, attr)
        if convert_to_str is True and not result:
            return '<none>'
        elif convert_to_str is True and isinstance(result, list):
            return ', '.join(result)
        elif convert_to_str is True:
            return str(result)
        else:
            return result

