    try:
        if header:
            header += '\n'
        lines = [ raw_input(header + ps1) ]
    except EOFError:
        return []
    terminate = [ terminate_str ]
    try:
        while lines[-1:] != terminate:
            new_line = raw_input(ps1)
            while new_line.endswith('\\'):
                new_line = new_line[:-1] + raw_input(ps2)
